npx --yes --package @playwright/cli playwright-cli eval "() => { const cw = document.documentElement.clientWidth; const bad = []; document.querySelectorAll('h1, .btn-row, .container').forEach(el => { const r = el.getBoundingClientRect(); if (r.right > cw + 1) bad.push(el.tagName + '|' + String(el.className && el.className.baseVal !== undefined ? el.className.baseVal : el.className).slice(0, 60) + '|r=' + Math.round(r.right) + '|l=' + Math.round(r.left) + '|w=' + Math.round(r.width)); }); const btn = document.querySelector('.btn-row .btn'); const chain = []; let n = btn; while (n && n !== document.body) { const r = n.getBoundingClientRect(); chain.push(n.tagName + '|' + String(n.className && n.className.baseVal !== undefined ? n.className.baseVal : n.className).slice(0,50) + '|r=' + Math.round(r.right) + '|l=' + Math.round(r.left) + '|w=' + Math.round(r.width)); n = n.parentElement; } return 'BAD: ' + bad.slice(0,10).join(' ;; ') + ' || BTNCHAIN: ' + chain.slice(0, 12).join(' < '); }" > $null 2>&1
